import React, { useState } from 'react';
import ManageTeachers from './ManageTeachers';
import ManageStudents from './ManageStudents';
import ManageSubjects from './ManageSubjects';
import ManageTimetable from './ManageTimetable';
import Sidebar from './Sidebar';
import logo from '../logo.png';
import DashboardOverview from './DashboardOverview';

export default function LmsDashboard({ userName, handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  // 🟢 සයිඩ්බාර් එකෙන් ක්ලික් කරන පිටුව අනුව මැද පෙන්වන කොටස
  const renderSubPage = () => {
    switch (currentSubPage) {
      case 'Overview':
        return <DashboardOverview />;

      case 'Manage Teachers':
        return <ManageTeachers />;
          
      case 'Manage Students':
        return <ManageStudents />;
          
      case 'Manage Subjects': // 🟢 මේක අලුතෙන් හැදුවා
        return <ManageSubjects />;

      case 'Manage Classes': // 🟢 මේක නිවැරදි කළා
        return <ManageTimetable />;  
        
      case 'Reports':
        return (
          <div style={{ padding: '30px', backgroundColor: '#fff', borderRadius: '15px', height: '100%', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '15px', marginBottom: '20px' }}>
              <span style={{ fontSize: '32px' }}>📊</span>
              <h2 style={{ color: '#1e293b', margin: 0 }}>System Reports</h2>
            </div>
            <p style={{ color: '#64748b', fontSize: '16px', lineHeight: '1.6' }}>
              Student performance analytics, attendance summaries, and monthly active user reports will be generated here. 
              <br/><br/>
              <span style={{ color: '#f59e0b', fontWeight: 'bold' }}>⚠️ Note: Report generation module is currently under development.</span>
            </p>
          </div>
        );

      case 'Feedback':
        return (
          <div style={{ padding: '30px', backgroundColor: '#fff', borderRadius: '15px', height: '100%', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '15px', marginBottom: '20px' }}>
              <span style={{ fontSize: '32px' }}>💬</span>
              <h2 style={{ color: '#1e293b', margin: 0 }}>Student Feedback</h2>
            </div>
            <div style={{ backgroundColor: '#f8fafc', padding: '20px', borderRadius: '10px', borderLeft: '4px solid #3b82f6' }}>
              <h4 style={{ margin: '0 0 10px 0', color: '#1e293b' }}>Recent Inquiries</h4>
              <p style={{ color: '#64748b', margin: 0 }}>No new feedback or messages from students at the moment.</p>
            </div>
          </div>
        );

      case 'Settings':
        return (
          <div style={{ padding: '30px', backgroundColor: '#fff', borderRadius: '15px', height: '100%', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '15px', marginBottom: '20px' }}>
              <span style={{ fontSize: '32px' }}>⚙️</span>
              <h2 style={{ color: '#1e293b', margin: 0 }}>Administrator Settings</h2>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px' }}>
              <div style={{ padding: '20px', border: '1px solid #e2e8f0', borderRadius: '10px' }}>
                <h4 style={{ margin: '0 0 10px 0', color: '#15803d' }}>Institute Profile</h4>
                <p style={{ color: '#64748b', fontSize: '14px' }}>Update institute name, logo, and contact information.</p>
                <button style={{ padding: '8px 15px', backgroundColor: '#f1f5f9', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', color: '#334155' }}>Configure</button>
              </div>
              <div style={{ padding: '20px', border: '1px solid #e2e8f0', borderRadius: '10px' }}>
                <h4 style={{ margin: '0 0 10px 0', color: '#15803d' }}>Security & Passwords</h4>
                <p style={{ color: '#64748b', fontSize: '14px' }}>Change administrator password and manage access controls.</p>
                <button style={{ padding: '8px 15px', backgroundColor: '#f1f5f9', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', color: '#334155' }}>Manage Security</button>
              </div>
            </div>
          </div>
        );

      default:
        return <DashboardOverview />;
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', backgroundColor: '#f1f5f9', overflow: 'hidden', boxSizing: 'border-box' }}>
      
      {/* 🟢 Top Header */}
      <header style={{ 
        height: '90px', backgroundColor: '#ffffff', display: 'flex', 
        alignItems: 'center', justifyContent: 'space-between', padding: '0 40px', 
        borderBottom: '1px solid #e2e8f0', zIndex: 10,
        boxShadow: '0 2px 8px rgba(0,0,0,0.03)'
      }}>
        <img src={logo} alt="Logo" style={{ height: '62px', width: 'auto' }} /> 
        
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
          <div style={{ fontSize: '20px', fontWeight: '700', color: '#1e293b' }}>
            Welcome, {userName || 'Admin'} 👋
          </div>
          
          <div style={{ 
            width: '45px', height: '45px', borderRadius: '50%', 
            backgroundColor: '#e2e8f0', display: 'flex', 
            alignItems: 'center', justifyContent: 'center',
            border: '2px solid #15803d', color: '#64748b'
          }}>
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
              <circle cx="12" cy="7" r="4"></circle>
            </svg>
          </div>
        </div>
      </header>

      {/* 🟢 Main Body */}
      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        
        <div style={{ width: '260px', backgroundColor: '#15803d', display: 'flex', flexDirection: 'column', height: '100%', overflowY: 'hidden' }}>
          <Sidebar 
            currentSubPage={currentSubPage} 
            setCurrentSubPage={setCurrentSubPage} 
            onLogoutClick={handleLogout} 
          />
        </div>

        <div style={{ flex: 1, padding: '24px', overflowY: 'auto', height: '100%' }}>
          {renderSubPage()}
        </div>

      </div>
    </div>
  );
}
